def asignar_espacios_existentes(apps, schema_editor):
    Empresa = apps.get_model("cuentas", "Empresa")
    Usuario = apps.get_model("cuentas", "Usuario")
    for usuario in Usuario.objects.filter(empresa__isnull=True).iterator():
        titular = " ".join((usuario.first_name, usuario.last_name)).strip()
        nombre = titular or usuario.email.split("@", 1)[0]
        empresa = Empresa.objects.create(nombre=f"{nombre} (espacio de trabajo)")
        usuario.empresa_id = empresa.pk
        if usuario.rol == "director":
            usuario.rol = "manager"
        usuario.save(update_fields=("empresa", "rol"))


